n("מילן", "מילן הוא שם סלאבי שפירושו יקר או אהוב, והוא נפוץ בסרבית, בצ׳כית ובסלובקית. בעברית השם נשמע גם כמו העיר מילאנו באיטליה. השם ניתן גם לבנים וגם לבנות, וקרובה אליו צורת הנקבה מילנה.", ["מילנה"])
n("מורל", "מורל הוא שם עברי חדש, וכנראה הוא צורה של מוראל, שבנוי מהמילים מור ואל. מור הוא צמח בושם יקר. השם ניתן לבנות, והוא נדיר בארץ. בצרפתית מורל הוא גם שם משפחה מוכר.", ["מוראל", "מור"])
n("מידד", "מידד הוא שם מקראי שקשור כנראה למילה דוד, אהוב. בספר במדבר מסופר על אלדד ומידד, שני זקנים שהתנבאו במחנה, ומשה אמר שהלוואי שכל העם יהיו נביאים. השם ניתן לבנים, והוא נדיר.", ["אלדד"])
n("איטן", "איטן הוא כתיב של איתן, שם עברי שפירושו חזק ויציב. בכתיב הזה השם נשמע גם כמו הצורה האנגלית איתן, שנפוצה מאוד באמריקה. השם ניתן לבנים, והכתיב איטן נדיר בארץ.", ["איתן"])
n("עדנה", "עדנה הוא שם עברי מהמילה עדנה, רוך ועונג. מאותו שורש באים גם השמות עדן ועדינה. השם היה נפוץ בארץ בשנות הארבעים והחמישים, והוא ניתן לבנות. גם באנגלית יש שם עדנה, שמקורו אירי.", ["עדן", "עדינה"])
n("סטפן", "סטפן הוא שם שבא מהמילה היוונית סטפנוס, כתר או זר. השם נפוץ בשפות רבות באירופה, ובאנגלית הוא נכתב סטיבן. בארץ השם הגיע עם העלייה מאירופה, והוא ניתן לבנים. מוכרת גם צורת הנקבה סטפני.", ["סטפני"])
n("מגי", "מגי היא צורת חיבה אנגלית של מרגרט, שם שבא מהמילה היוונית מרגריטס, פנינה. השם היה נפוץ באנגליה ובאירלנד, והוא ניתן לבנות. בארץ השם נדיר, והוא נשמע קליל וחם.", [])
n("עירד", "עירד הוא שם מקראי. בספר בראשית עירד הוא בנו של חנוך ונכדו של קין, באחד מדורות האדם הראשונים. השם ניתן לבנים, והוא נדיר. בצליל הוא קרוב לשם העיר ערד שבנגב.", ["ערד"])
n("ששון", "ששון הוא שם עברי מהמילה ששון, שמחה גדולה. בספר ישעיהו ששון ושמחה באים יחד עם הגאולה. השם ניתן לבנים, והוא היה נפוץ בעיקר בקהילות של יהודי עיראק ופרס, שם הוא מוכר גם כשם משפחה.", ["שושן"])
n("גבי", "גבי הוא צורת חיבה של גבריאל ושל גבריאלה, ובשפות אחרות גם של גבריאל בכתיב גבריאל. השם גבריאל פירושו אלוהים הוא הכוח שלי. השם ניתן גם לבנים וגם לבנות, והוא נשמע חם וקצר.", ["גבריאל", "גבריאלה"])
n("קטי", "קטי היא צורת חיבה של קתרין, ובאנגלית היא נכתבת קייטי. השם קתרין בא כנראה מהמילה היוונית קתרוס, טהור. בארץ השם נדיר, והוא ניתן לבנות. מוכרות גם הצורות קטיה וקייט.", ["קטיה", "קייט"])
n("אלרן", "אלרן הוא שם עברי חדש שבנוי מהמילים אל ורן, ופירושו אלוהים שר. המילה רן באה מהשורש ר־נ־ן, שירה ושמחה. השם ניתן לבנים, והוא נדיר. קרוב אליו מאוד השם אלירן.", ["אלירן", "אלירון"])
n("אלירון", "אלירון הוא שם עברי חדש שבנוי מהמילים אלי ורון, ופירושו האל שלי הוא השירה שלי. השם קרוב לשמות כמו אלירן ורון, והוא נשמע שמח ומוזיקלי. השם ניתן לבנים.", ["רון", "אלירן"])
n("אבא", "אבא היא המילה הארמית לאב, והיא שימשה כשם בקהילות רבות, במיוחד בתקופת התלמוד, למשל אבא שאול ואבא חלקיה. השם ניתן לבנים, והוא מוכר גם בקהילות בעולם, כמו אבא אבן, שר החוץ של ישראל.", ["אבי"])
n("לי שי", "לי שי הוא שם עברי חדש שבנוי מהמילים לי ושי, ופירושו יש לי מתנה. השם שייך לקבוצה של שמות שמתחילים במילה לי, כמו ליאור וליאל. הוא ניתן גם לבנים וגם לבנות, והוא נדיר.", ["שי", "ליאור"])
n("לריאן", "לריאן הוא שם חדש ונדיר, וכנראה הוא צורה של לורין או של לוריאן. הצליל שלו רך ובינלאומי. השם ניתן לבנות, והוא קרוב בצליל לשמות כמו לורן ולוריאן.", ["לוריאן", "לורן"])
n("אולג", "אולג הוא שם סלאבי שמקורו בשם הנורדי הלגי, שפירושו קדוש או מבורך. ברוסיה העתיקה זה היה שמו של אחד הנסיכים הראשונים של קייב. בארץ השם הגיע עם העלייה מברית המועצות, והוא ניתן לבנים.", ["אולגה"])
n("ימימה", "ימימה היא בתו של איוב. בסוף ספר איוב, אחרי כל הצרות, נולדו לאיוב שלוש בנות, ונאמר שלא היו נשים יפות כמותן בכל הארץ. השם ניתן לבנות, ויש שקושרים אותו למילה יום.", [])
n("מרין", "מרין הוא שם צרפתי שבא מהמילה הלטינית מרינוס, של הים. השם נפוץ בצרפת, ובארץ הוא נשמע קרוב לשמות מירן ומורן. השם ניתן לבנות, והוא נדיר. קרובה אליו גם הצורה מרינה.", ["מרינה", "מורן"])
n("נאורה", "נאורה הוא שם עברי מהמילה נאור, מואר ומשכיל. מאותה מילה בא גם השם נאור. השם ניתן לבנות, והוא נשמע בהיר ורך. נאורה הוא שם נדיר, אבל ברור לכל דובר עברית.", ["נאור"])
n("קייט", "קייט הוא קיצור אנגלי של קתרין, והוא נפוץ באנגליה ובאמריקה גם כשם בפני עצמו. השם קתרין בא כנראה מהמילה היוונית קתרוס, טהור. בארץ השם נדיר, והוא ניתן לבנות.", ["קטי", "קטיה"])
n("ויקי", "ויקי היא צורת חיבה של ויקטוריה, שם לטיני שפירושו ניצחון. השם נפוץ בשפות רבות, והוא היה מוכר בארץ בשנות השישים והשבעים. השם ניתן לבנות, והוא נשמע קליל ושמח.", ["ויקה"])
n("חופית", "חופית היא ציפור קטנה שחיה לחוף הים ולחוף האגמים, ומחפשת מזון בחול הרטוב. השם עברי, והוא קשור גם למילה חוף. השם ניתן לבנות, והוא שייך לקבוצה של שמות מעולם הציפורים.", ["חוף"])
n("מוניקה", "מוניקה הוא שם בינלאומי ממקור לטיני, ויש שקושרים אותו למילה מונרה, להזכיר או ליעץ. השם נפוץ באיטלקית, בפולנית ובשפה הספרדית, והוא ניתן לבנות. בצרפתית מוכרת הצורה מוניק.", ["מוניק"])
n("רמה", "רמה הוא שם עברי מהמילה רמה, מקום גבוה. מאותו שורש באים השמות המוכרים רם, רומי ורמי. השם ניתן לבנות, והוא נדיר. רמה הוא גם שמם של כמה יישובים בארץ, כמו ראמה שבגליל.", ["רם", "רומי"])
n("פולי", "פולי היא צורת חיבה אנגלית של מרי, ומרי בא מהשם העברי מרים. באנגלית השם מוכר מאוד, גם מסיפורי ילדים. בארץ השם נדיר, והוא ניתן לבנות. הוא נשמע קליל ושמח.", ["מרים"])
n("יונדב", "יונדב הוא שם מקראי שבנוי מהמילים יהו ונדב, ופירושו ה׳ נדיב. בספר שמואל יונדב הוא בן דודו של אמנון, ונאמר עליו שהיה איש חכם מאוד. השם ניתן לבנים, והוא נדיר. מוכרת גם הצורה יהונדב.", ["יהונדב", "נדב"])
n("ג'ק", "ג׳ק הוא שם אנגלי, צורת חיבה של ג׳ון, שבא מהשם העברי יוחנן, ה׳ חנן. באנגליה ובאירלנד ג׳ק הוא אחד השמות הנפוצים ביותר לבנים. בארץ השם נדיר, אבל הוא קצר וקל לבטא.", ["יוחנן"])
n("גונן", "גונן הוא שם עברי מהשורש ג־נ־ן, הגנה ושמירה. מאותו שורש באה המילה מגן. השם ניתן לבנים, והוא היה נפוץ בארץ בשנות החמישים והשישים. הוא נשמע חזק ושקט.", [])
n("לאונרדו", "לאונרדו הוא שם איטלקי שבא מגרמנית עתיקה, ופירושו חזק כמו אריה. השם התפרסם בזכות לאונרדו דה וינצ׳י, הצייר והממציא. בארץ השם נדיר, והוא ניתן לבנים.", [])
n("ליקה", "ליקה היא צורת חיבה של שמות כמו אנג׳ליקה ואנג׳לינה. בשפות של מזרח אירופה השם נשמע קצר וחם. השם ניתן לבנות, והוא נדיר בארץ. קרוב אליו בצליל השם ליה.", ["ליה"])
n("קרלה", "קרלה הוא הצורה הנשית של קרל, שם גרמני שפירושו אדם חופשי. השם נפוץ באיטלקית, בגרמנית ובשפה הספרדית. בארץ הוא נדיר, והוא ניתן לבנות. בעברית הוא נשמע קרוב לקורל.", ["קורל"])
n("אלית", "אלית הוא שם עברי חדש מהמילה אל, וכנראה הוא צורה של אלה או של אליה. השם קצר ורך, והוא ניתן לבנות. יש שקושרים אותו גם למילה האנגלית עילית, הטובים ביותר.", ["אלה", "אליה"])
n("אוניל", "אוניל הוא שם חדש ונדיר, ויש שקוראים בו את המילים און ואל, כוחו של אלוהים. באנגלית אוניל הוא גם שם משפחה אירי מוכר. השם ניתן גם לבנים וגם לבנות.", [])
n("אסי", "אסי הוא צורת חיבה של אסף, ולפעמים של אסתר. השם אסף בא מהשורש א־ס־ף, איסוף וכינוס. אסי היה נפוץ בארץ בשנות השבעים, והוא ניתן לבנים, אבל לפעמים גם לבנות.", ["אסף", "אסא"])
n("מורג", "מורג הוא כלי עבודה עתיק לדישת תבואה. בספר ישעיהו נאמר שהעם יהיה כמו מורג חדש וחד. השם ניתן לבנות, והוא מוכר בארץ גם כשמו של יישוב שהיה ברצועת עזה.", [])
n("ישורון", "ישורון הוא שם שירי לעם ישראל, והוא קשור כנראה למילה יושר. בספר ישעיהו ישורון מופיע לצד יעקב, כשם של חיבה לעם. השם ניתן לבנים, והוא נדיר ומכובד.", ["ישראל"])
n("גיה", "גיה הוא שם חדש ונדיר, וכנראה הוא צורה של גאיה, אמא האדמה במיתולוגיה היוונית. בעברית השם נשמע גם קרוב לגיא. השם ניתן גם לבנים וגם לבנות.", ["גיא", "גאיה"])
n("נובה", "נובה היא המילה הלטינית לחדשה. באסטרונומיה נובה היא כוכב שמתבהר פתאום מאוד, ואחר כך דועך. בעברית השם נשמע קרוב לנוב, פרי ויבול. השם ניתן לבנות, והוא נדיר.", ["ניבה"])
n("צהלי", "צהלי הוא שם עברי מהמילה צהלה, שמחה וקריאה של שמחה, ופירושו השמחה שלי. מאותה מילה באים גם השמות צהל וצהלה. השם ניתן לבנות, והוא נדיר.", ["צהלה", "צהל"])
n("צפנת", "צפנת הוא שם שבא מתוך צפנת פענח, השם המצרי שנתן פרעה ליוסף בספר בראשית. בעברית נוטים לקרוא בו את המילים צפון ופענוח, מי שמגלה סודות. השם ניתן לבנות, והוא נדיר.", ["צפניה"])
n("שלווה", "שלווה הוא שם עברי מהמילה שלווה, שקט ורוגע. מאותו שורש באים גם השמות שליו ושלו. השם ניתן גם לבנים וגם לבנות, אבל בעיקר לבנות. הוא נשמע רך ומרגיע.", ["שליו", "שלו"])
n("אייזיק", "אייזיק הוא הצורה האנגלית של יצחק, אחד משלושת האבות. השם נפוץ באנגליה ובאמריקה, והוא מוכר בזכות אייזק ניוטון. בארץ השם נדיר, והוא ניתן לבנים.", ["יצחק"])
n("אנני", "אנני הוא שם חדש ונדיר, וכנראה הוא צורה של אנה או של אן. השם אנה בא מהשם העברי חנה, שפירושו חן. השם ניתן לבנות, והוא נשמע רך ובינלאומי.", ["אנה", "חנה"])
n("אדירה", "אדירה הוא שם עברי מהמילה אדיר, חזק ונהדר. מאותו שורש באים גם השמות אדיר ואדר. השם ניתן לבנות, והוא נשמע חזק ומכובד. בארץ הוא נדיר יחסית.", ["אדיר", "אדר"])
n("באשא", "באשא הוא שם ביידיש, צורת חיבה של בתיה או של בת־שבע. בקהילות של מזרח אירופה נבנו הרבה צורות קצרות לשמות עבריים, כמו באשה ובאשקה. השם ניתן לבנות, והוא נדיר היום.", ["בתיה"])
n("זיוה", "זיוה הוא שם עברי מהמילה זיו, אור וברק. מאותה מילה באים גם השמות זיו וזיוית. השם היה נפוץ בארץ בשנות הארבעים והחמישים, והוא ניתן לבנות.", ["זיו"])
n("נתי", "נתי הוא צורת חיבה של נתנאל ושל נתן, שמות מהשורש נ־ת־ן, נתינה ומתנה. השם ניתן בעיקר לבנים, אבל לפעמים גם לבנות. הוא נשמע קליל וחם.", ["נתנאל", "נתן"])
n("קלי", "קלי הוא שם אירי, ויש שקושרים אותו למילה האירית למלחמה. באמריקה השם היה נפוץ מאוד בשנות השמונים. בארץ השם נדיר, והוא ניתן לבנות. קרוב אליו בצליל השם קיילי.", ["קיילי"])
n("מלכיאל", "מלכיאל הוא שם מקראי שבנוי מהמילים מלכי ואל, ופירושו אלוהים הוא המלך שלי. בספר בראשית מלכיאל הוא נכדו של אשר, אחד מבני יעקב שירדו למצרים. השם ניתן לבנים, והוא נדיר.", ["מלכה", "אלימלך"])
n("נטעלי", "נטעלי הוא שם עברי חדש שבנוי מהמילים נטע ולי, ופירושו הנטע שלי. השם נשמע רך ומשפחתי, והוא קרוב לשמות כמו נטע ונטלי. השם ניתן לבנות.", ["נטע"])
